import unittest

from hourglass.models import Span
from hourglass.rounding import round_span_labels

class RoundingTests(unittest.TestCase):
    def test_label(self):
        self.assertEqual(
            round_span_labels([Span(9 * 60 + 2, 17 * 60 + 12)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        self.assertEqual(
            round_span_labels([Span(0, 65)], 10), ["00:00-01:10 (1h 10m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_span_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_span_labels([Span(0, 60)], step)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span_labels([Span(1, 3)], 15)
